    tolerance: tolField > 0 ? tolField : 0,
    tolScale: state.prec,
    angleTolDeg: Math.max(0.01, parseFloat($('ang').value) || 0.25) * (state.prec >= 4 ? 2 : 1),
    types: { cyl: $('tCyl').checked, cone: $('tCone').checked, sphere: $('tSph').checked, torus: $('tTor').checked },
