  $('rCyl').textContent = fmtInt(s.cylinders);
  $('rCone').textContent = fmtInt(s.cones);
  $('rSph').textContent = fmtInt(s.spheres);
  $('rTor').textContent = fmtInt(s.tori);
  $('rEdges').textContent = fmtInt(s.edges) + ' / ' + fmtInt(s.verts);
  $('rDev').textContent = fmtLen(s.maxDeviation) + ' ' + u;
  $('rVol').textContent = s.solid ? fmtLen(s.volume) + ' ' + u + '\xB3' : '\u2013';
  const b = s.bbox; $('rSize').textContent = [0,1,2].map(i => fmtLen(b.max[i]-b.min[i])).join(' \xD7 ');
