      if (j < ny - 1 && v0 !== (F[at(i, j + 1, l)] < 0)) quad(cid[cat(i - 1, j, l - 1)], cid[cat(i - 1, j, l)], cid[cat(i, j, l)], cid[cat(i, j, l - 1)], v0);
